import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static long [] P;
    static int m ;
    
    static long g(int a , int b){
        return 2 * P[a]  + P[a+2*b] + 3 *P[m-2*a-b];
    }
	public static void main (String[] args) throws java.lang.Exception
	{
	    StreamTokenizer s = new StreamTokenizer(new BufferedInputStream(System.in));
	    s.nextToken();
	    int t = (int) s.nval;
	    StringBuilder o = new StringBuilder();
	    while(t-->0){
	        s.nextToken();
	        int n = (int) s.nval;
	        m = 3*n;
	        long [] a = new long [m];
	        for(int i =0; i <m ; i++){
	            s.nextToken();
	            a[i]= (long)s.nval;
	        }
	        Arrays.sort(a);
	        P = new long[m+1];
	        for(int i =0; i<m; i++) P[i+1] = P[i]+ a[m-1-i];
	        long r = 0;
	        for(int b = 0; b<=n; b++){
	            int lo = 0, hi = n-b;
	            while(lo<hi){
	                int md = (lo+hi)/2;
	                if(g(md+1,b)>g(md,b)) lo =md+1;
	                else hi = md;
	            }
	            r = Math.max(r, g(lo, b));
	        }
	        o.append(r).append("\n");
	        }
	        System.out.println(o);

	}
}
